        self.pollId = pollId
        self.title = title
        self.creator = creator
        self.phase = phase
        self.createdAt = createdAt
        self.ballots = ballots
    }

    enum CodingKeys: String, CodingKey {
        case pollId = "poll_id"
        case title
        case creator
        case phase
        case createdAt = "created_at"
        case ballots
    }
}

