        self.state = state
        self.trustees = trustees
        self.turnout = turnout
        self.myDigest = myDigest
        self.canVote = canVote
    }

    enum CodingKeys: String, CodingKey {
        case pollId = "poll_id"
        case definition
        case state
        case trustees
        case turnout
        case myDigest = "my_digest"
        case canVote = "can_vote"
    }
}

